def check_solution(x, n):
    val = x**n + x - 2
    if val <= 0:
        return None

    # Check if val is a power of 2
    if (val & (val - 1) == 0) and val > 0:
        k = val.bit_length() - 1
        return k
    return None

solutions = []
# Check n=3, x > 3
for x in range(4, 15):
    k = check_solution(x, 3)
    if k is not None:
        solutions.append((x, 3, k))

print(f"Solutions found for n=3 (x<=14): {solutions}")

